import re
RISKY = {
    "식품": ["치료", "예방", "면역력 강화", "다이어트 효과", "혈당을 낮"],
    "화장품": ["피부 재생", "아토피", "여드름 치료", "주름 제거", "셀룰라이트"],
}

def check(category, copy):
    return [w for w in RISKY[category] if re.search(re.escape(w), copy)]

print(check("식품", "아침 한 잔으로 면역력 강화! 감기 예방까지"))  # ['예방', '면역력 강화']
print(check("식품", "국산 귀리 100%, 한 봉에 식이섬유 5g"))        # []
print(check("화장품", "바르는 순간 피부 재생, 주름 제거"))          # ['피부 재생', '주름 제거']
